package cn.zhuatech.cms.controller; import cn.zhuatech.cms.common.ApiResponse; import cn.zhuatech.cms.dto.CmsDto.*; import cn.zhuatech.cms.service.CmsService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('EDITOR','ADMIN')") public class EditorController {private final CmsService service;public EditorController(CmsService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}}
